package com.yuegang.zhihui.ai.application;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway.ToolEvidence;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.search.api.SearchHit;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.regex.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
public final class ChatService{
 private static final String SYSTEM="你是跨境智汇企业客服。只能依据提供的已审核资料和系统提供的只读工具结果回答；必须标注引用；资料不足时明确拒答；不得生成SQL、修改订单、调整余额或发布知识。";private static final Pattern SKU=Pattern.compile("(?:SKU|商品)[：: #]*(\\d{1,20})",Pattern.CASE_INSENSITIVE),ORDER=Pattern.compile("订单[号ID：: #]*(\\d{1,20})",Pattern.CASE_INSENSITIVE);private final RetrievalGateway retrieval;private final ModelGateway model;private final CommerceToolGateway tools;private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final ObjectMapper json;
 public ChatService(RetrievalGateway retrieval,ModelGateway model,CommerceToolGateway tools,DataSource dataSource){this(retrieval,model,tools,dataSource,new ObjectMapper());}public ChatService(RetrievalGateway retrieval,ModelGateway model,CommerceToolGateway tools,DataSource dataSource,ObjectMapper json){this.retrieval=retrieval;this.model=model;this.tools=tools;jdbc=new JdbcTemplate(dataSource);tx=new TransactionTemplate(new DataSourceTransactionManager(dataSource));this.json=json;}
 public ChatResponse chat(long user,ChatRequest request){long retrievalStarted=System.nanoTime();List<SearchHit>hits=retrieval.search(request.message(),request.category(),8);long retrievalMs=elapsed(retrievalStarted);List<ToolEvidence>evidence=new ArrayList<>();Matcher sku=SKU.matcher(request.message());if(sku.find())evidence.add(tools.product(sku.group(1)));if(request.includeOwnOrders()){Matcher order=ORDER.matcher(request.message());if(order.find())evidence.add(tools.ownOrder(user,order.group(1)));}boolean professional=request.message().matches(".*(政策|法规|通关|关税|溯源|原产地).*?");var prompt=activePrompt();if(hits.isEmpty()&&evidence.isEmpty()&&professional)return save(user,request,"当前已审核知识库中没有足够依据，无法可靠回答该专业问题。",List.of(),List.of(),true,"INSUFFICIENT_EVIDENCE",new Trace(retrievalMs,0,prompt,0,0,hits));String context=hits.stream().map(hit->"["+hit.documentId()+"/"+hit.chunkId()+"] "+hit.title()+"\n"+hit.excerpt()).reduce("",(left,right)->left+"\n"+right);String toolContext=evidence.stream().map(value->"[只读工具 "+value.name()+"] "+value.resultJson()).reduce("",(left,right)->left+"\n"+right);String userPrompt="已审核资料：\n"+context+"\n只读业务数据：\n"+toolContext+"\n\n问题："+request.message();long modelStarted=System.nanoTime();String answer=model.answer(SYSTEM,userPrompt);long modelMs=elapsed(modelStarted);List<CitationView>citations=hits.stream().map(hit->new CitationView("KNOWLEDGE",hit.chunkId(),hit.title(),hit.excerpt(),null,hit.documentVersion(),hit.sourceUpdatedAt())).toList();return save(user,request,answer,citations,evidence,false,null,new Trace(retrievalMs,modelMs,prompt,tokens(SYSTEM)+tokens(userPrompt),tokens(answer),hits));}
 private ChatResponse save(long user,ChatRequest request,String answer,List<CitationView>citations,List<ToolEvidence>tools,boolean refused,String reason,Trace trace){return tx.execute(status->{long conversation=request.conversationId()==null||request.conversationId().isBlank()?next():Long.parseLong(request.conversationId());Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM ai_conversation WHERE id=? AND user_id=?",Integer.class,conversation,user);if(request.conversationId()!=null&&!request.conversationId().isBlank()&&owned==0)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("INSERT INTO ai_conversation(id,user_id,title) VALUES(?,?,?) ON DUPLICATE KEY UPDATE updated_at=NOW(6)",conversation,user,request.message().substring(0,Math.min(100,request.message().length())));jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content) VALUES(?,?,'USER',?)",next(),conversation,request.message());long message=next();jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content,refused,model_name,prompt_tokens,completion_tokens) VALUES(?,?,'ASSISTANT',?,?,?,?,?)",message,conversation,answer,refused,trace.prompt.modelName,trace.promptTokens,trace.completionTokens);int sequence=0;for(var citation:citations)jdbc.update("INSERT INTO ai_citation(message_id,sequence_no,source_type,source_id,title,excerpt,url) VALUES(?,?,?,?,?,?,?)",message,sequence++,citation.sourceType(),citation.sourceId(),citation.title(),citation.excerpt(),citation.url());for(var tool:tools)jdbc.update("INSERT INTO ai_tool_call(id,message_id,tool_name,arguments_json,result_digest,status) VALUES(?,?,?,?,?,'SUCCEEDED')",next(),message,tool.name(),tool.argumentsJson(),tool.digest());jdbc.update("INSERT INTO ai_rag_trace(id,message_id,query_digest,retrieval_evidence_json,prompt_config_id,prompt_version,model_name,retrieval_duration_ms,model_duration_ms,prompt_tokens_estimated,completion_tokens_estimated) VALUES(?,?,?,?,?,?,?,?,?,?,?)",next(),message,digest(request.message()),write(trace.hits),trace.prompt.id,trace.prompt.version,trace.prompt.modelName,trace.retrievalMs,trace.modelMs,trace.promptTokens,trace.completionTokens);return new ChatResponse(Long.toString(conversation),Long.toString(message),answer,citations,refused,reason);});}
 private Prompt activePrompt(){return jdbc.query("SELECT id,version,model_name FROM ai_prompt_config WHERE enabled=TRUE ORDER BY updated_at DESC LIMIT 1",r->r.next()?new Prompt(r.getLong(1),r.getLong(2),r.getString(3)):new Prompt(null,null,"doubao"));}private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new BusinessException(ErrorCode.INTERNAL_ERROR);}}private static int tokens(String value){return Math.max(1,value==null?0:value.codePointCount(0,value.length())/2);}private static long elapsed(long started){return (System.nanoTime()-started)/1_000_000;}private static String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception impossible){throw new IllegalStateException(impossible);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private record Prompt(Long id,Long version,String modelName){}private record Trace(long retrievalMs,long modelMs,Prompt prompt,int promptTokens,int completionTokens,List<SearchHit>hits){}
}
